package mz.co.aprendaacodar.course.entity;
import jakarta.persistence.*;import mz.co.aprendaacodar.common.entity.BaseEntity;import mz.co.aprendaacodar.common.enums.Enums.LessonStatus;
@Entity @Table(name="lessons") public class Lesson extends BaseEntity {@ManyToOne(optional=false,fetch=FetchType.LAZY) private Course course;@ManyToOne(fetch=FetchType.LAZY) private CourseModule module;@Column(nullable=false,length=180) private String title;@Column(columnDefinition="TEXT") private String description;@Column(nullable=false,length=20) private String youtubeVideoId;private Integer videoDurationSeconds;@Column(nullable=false) private int position;@Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private LessonStatus status=LessonStatus.DRAFT;protected Lesson(){}public Lesson(Course c,CourseModule m,String t,String d,String video,Integer duration,int p){course=c;module=m;title=t;description=d;youtubeVideoId=video;videoDurationSeconds=duration;position=p;status=LessonStatus.PUBLISHED;}public Course getCourse(){return course;}public CourseModule getModule(){return module;}public String getTitle(){return title;}public String getDescription(){return description;}public String getYoutubeVideoId(){return youtubeVideoId;}public Integer getVideoDurationSeconds(){return videoDurationSeconds;}public int getPosition(){return position;}public LessonStatus getStatus(){return status;}public void update(CourseModule m,String t,String d,String video,Integer duration,int p){module=m;title=t;description=d;youtubeVideoId=video;videoDurationSeconds=duration;position=p;}public void setPosition(int p){position=p;}}
